using namespace std;
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    vector<int> p(n), f(n), sz(n, 1);
    iota(f.begin(), f.end(), 0);
    for (int &x : p)
        cin >> x;
    auto find = [&](int x) {
        while (x != f[x])
            x = f[x] = f[f[x]];
        return x;
    };
    while (m--) {
        int a, b;
        cin >> a >> b;
        a = find(a - 1);
        b = find(b - 1);
        if (a != b) {
            if (sz[a] < sz[b])
                swap(a, b);
            f[b] = a;
            sz[a] += sz[b];
        }
    }
    vector<vector<int>> g(n);
    for (int i = 0; i < n; i++)
        g[find(i)].push_back(i);
    for (auto &v : g) {
        vector<int> w;
        for (int i : v)
            w.push_back(p[i]);
        sort(w.rbegin(), w.rend());
        for (int j = 0; j < (int)v.size(); j++)
            p[v[j]] = w[j];
    }
    for (int i = 0; i < n; i++)
        cout << p[i] << (i + 1 == n ? '\n' : ' ');
}

