#include <bits/stdc++.h>
using namespace std;
int main() {
    int n;
    cin >> n;
    int v = n * n;
    vector<int> a(v), p(v), sz(v, 1);
    for (auto &x : a)
        cin >> x;
    iota(p.begin(), p.end(), 0);
    vector<array<int, 3>> e;
    for (int i = 0; i < v; i++) {
        if (i % n + 1 < n)
            e.push_back({abs(a[i] - a[i + 1]), i, i + 1});
        if (i + n < v)
            e.push_back({abs(a[i] - a[i + n]), i, i + n});
    }
    sort(e.begin(), e.end());
    auto find = [&](int x) {
        while (x != p[x])
            x = p[x] = p[p[x]];
        return x;
    };
    int ans = 0, need = (v + 1) / 2;
    if (need > 1)
        for (auto [w, u, t] : e) {
            u = find(u);
            t = find(t);
            if (u == t)
                continue;
            if (sz[u] < sz[t])
                swap(u, t);
            p[t] = u;
            sz[u] += sz[t];
            if (sz[u] >= need) {
                ans = w;
                break;
            }
        }
    cout << ans << '\n';
}

