import sys, bisect

s = sys.stdin.buffer.readline().strip().decode()
n = len(s)
d = [[0] * (n + 1) for _ in range(n + 1)]
mate = {"A": "U", "U": "A", "C": "G", "G": "C"}
positions = {c: [] for c in mate}
for i, c in enumerate(s):
    positions[c].append(i)
for l in range(n - 1, -1, -1):
    row = d[l]
    inner = d[l + 1]
    ks = positions[mate[s[l]]]
    ks = ks[bisect.bisect_right(ks, l) :]
    for r in range(l + 1, n):
        best = inner[r]
        for k in ks:
            if k > r:
                break
            value = 1 + inner[k - 1] + (d[k + 1][r] if k < r else 0)
            if value > best:
                best = value
        row[r] = best
print(d[0][n - 1] if n else 0)

