#include <bits/stdc++.h>
using namespace std;
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<vector<int>> a(n, vector<int>(n));
    vector<int> u(n), v(n), row_match(n, -1), column_match(n, -1);
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++) {
            cin >> a[i][j];
            u[i] = max(u[i], a[i][j]);
        }
    for (int root = 0; root < n; root++) {
        vector<int> slack(n, INT_MAX), from(n, -1), parent(n, -1);
        vector<bool> S(n), T(n);
        S[root] = true;
        int row = root;
        while (true) {
            for (int j = 0; j < n; j++)
                if (!T[j]) {
                    int candidate = u[row] + v[j] - a[row][j];
                    if (candidate < slack[j])
                        slack[j] = candidate, from[j] = row;
                }
            int delta = INT_MAX, column = -1;
            for (int j = 0; j < n; j++)
                if (!T[j]) {
                    if (slack[j] < delta ||
                        (slack[j] == delta && column_match[j] < 0 && column >= 0 &&
                         column_match[column] >= 0)) {
                        delta = slack[j];
                        column = j;
                    }
                }
            if (delta) {
                for (int i = 0; i < n; i++)
                    if (S[i])
                        u[i] -= delta;
                for (int j = 0; j < n; j++) {
                    if (T[j])
                        v[j] += delta;
                    else
                        slack[j] -= delta;
                }
            }
            parent[column] = from[column];
            if (column_match[column] < 0) {
                while (column >= 0) {
                    int i = parent[column], previous = row_match[i];
                    row_match[i] = column;
                    column_match[column] = i;
                    column = previous;
                }
                break;
            }
            T[column] = true;
            row = column_match[column];
            S[row] = true;
        }
    }
    int answer = 0;
    for (int i = 0; i < n; i++)
        answer += a[i][row_match[i]];
    cout << answer << '\n';
}

#include <bits/stdc++.h>
using namespace std;
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int m, n, H;
    while (cin >> m >> n >> H && m && n) {
        vector<vector<int>> a(m, vector<int>(n));
        for (auto &r : a)
            for (int &x : r)
                cin >> x;
        if (m > n) {
            vector<vector<int>> b(n, vector<int>(m));
            for (int i = 0; i < m; i++)
                for (int j = 0; j < n; j++)
                    b[j][i] = a[i][j];
            a = move(b);
            swap(m, n);
        }
        long long ans = 0;
        for (int l = 0; l < m; l++) {
            vector<int> s(n);
            for (int r = l; r < m; r++) {
                for (int j = 0; j < n; j++)
                    s[j] += a[r][j];
                int t = (H + r - l) / (r - l + 1);
                if (t > n)
                    continue;
                vector<long long> p(n + 1);
                for (int j = 0; j < n; j++)
                    p[j + 1] = p[j] + s[j];
                long long mn = 0;
                for (int j = t; j <= n; j++) {
                    mn = min(mn, p[j - t]);
                    ans = max(ans, p[j] - mn);
                }
            }
        }
        cout << ans << '\n';
    }
}

