import sys

it = iter(map(int, sys.stdin.buffer.read().split()))
out = []
while True:
    try:
        m, n, h = next(it), next(it), next(it)
    except StopIteration:
        break
    if not m or not n:
        break
    a = [[next(it) for _ in range(n)] for _ in range(m)]
    if m > n:
        a = list(zip(*a))
        m, n = n, m
    ans = 0
    for top in range(m):
        s = [0] * n
        for bottom in range(top, m):
            row = a[bottom]
            for j in range(n):
                s[j] += row[j]
            t = (h + bottom - top) // (bottom - top + 1)
            if t > n:
                continue
            p = [0]
            total = 0
            for x in s:
                total += x
                p.append(total)
            low = 0
            for j in range(t, n + 1):
                if p[j - t] < low:
                    low = p[j - t]
                if p[j] - low > ans:
                    ans = p[j] - low
    out.append(str(ans))
print("\n".join(out))

