#include <bits/stdc++.h>
using namespace std;
int main() {
    int a, b;
    cin >> a >> b;
    const int V = 1000001, INF = 1e9;
    vector<int> d(V, INF);
    array<deque<int>, 4> q;
    d[a] = 0;
    q[0].push_back(a);
    int pending = 1, t = 0;
    while (pending) {
        while (q[t % 4].empty())
            t++;
        int x = q[t % 4].front();
        q[t % 4].pop_front();
        pending--;
        if (d[x] != t)
            continue;
        if (x == b) {
            cout << t << '\n';
            break;
        }
        int y[] = {x - 1, x + 1, x - 2, x + 2, x * 2, x / 2};
        for (int k = 0; k < 6; k++)
            if (y[k] >= 0 && y[k] < V) {
                int nd = t + (k < 2 ? 2 : 3);
                if (nd < d[y[k]]) {
                    d[y[k]] = nd;
                    q[nd % 4].push_back(y[k]);
                    pending++;
                }
            }
    }
}

