    for (long long p = 2; p <= rem / p; p++) {
        if (rem % p)
            continue;
        long long q = 1;
        while (rem % p == 0)
            rem /= p, q *= p;
        vector<long long> roots;
        if (p != 2)
            roots = {1, q - 1};
        else if (q == 2)
            roots = {1};
        else if (q == 4)
