        else
            roots = {1, q - 1, 1 + q / 2, q / 2 - 1};
        long long x, y;
        eg(mod, q, x, y);
        x = (x % q + q) % q;
        vector<long long> b;
        for (long long a : ans)
            for (long long r : roots)
