    string a, b;
    int queries;
    cin >> a >> b >> queries;
    if (a.size() > b.size())
        swap(a, b);
    int n = a.size(), m = b.size(), size = 1;
    while (size < n)
        size *= 2;
    for (int query = 0; query < queries; query++) {
        vector<int> gap(26, max(n, m));
        string symbol;
        while (cin >> symbol && symbol != "$")
            cin >> gap[symbol[0] - 'A'];
        vector<vector<unsigned short>> tree(2 * size, vector<unsigned short>(m));
        int answer = 0;
        for (int i = 0; i < n; i++) {
            int g = gap[a[i] - 'A'], l = size + max(0, i - g - 1), r = size + i;
            vector<unsigned short> vertical(m), row(m);
            auto combine = [&](int node) {
                for (int j = 0; j < m; j++)
                    vertical[j] = max(vertical[j], tree[node][j]);
            };
            while (l < r) {
                if (l & 1)
                    combine(l++);
                if (r & 1)
                    combine(--r);
                l /= 2;
                r /= 2;
            }
            deque<int> q;
            for (int j = 0; j < m; j++) {
                if (j) {
                    while (!q.empty() && vertical[q.back()] <= vertical[j - 1])
                        q.pop_back();
                    q.push_back(j - 1);
                }
                while (!q.empty() && q.front() < j - g - 1)
                    q.pop_front();
                if (a[i] == b[j]) {
                    row[j] = 1 + (q.empty() ? 0 : vertical[q.front()]);
                    answer = max(answer, int(row[j]));
                }
            }
            int node = size + i;
            tree[node] = move(row);
            for (node /= 2; node; node /= 2)
                for (int j = 0; j < m; j++)
                    tree[node][j] = max(tree[2 * node][j], tree[2 * node + 1][j]);
        }
        if (query)
            cout << ' ';
        cout << answer;
    }
    cout << '\n';
}

