#include <boost/rational.hpp>
using Q = boost::rational<cpp_int>;
struct P {
    Q x, y;
};
Q cross(P a, P b, P c) {
    return (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x);
}
int main() {
    int m, n;
    cin >> m;
    vector<P> a(m);
    for (auto &p : a) {
        int x, y;
        cin >> x >> y;
        p = {Q(x), Q(y)};
    }
    cin >> n;
    vector<P> b(n);
    for (auto &p : b) {
        int x, y;
        cin >> x >> y;
        p = {Q(x), Q(y)};
    }
    for (int k = 0; k < n; k++) {
        vector<P> c;
        P u = b[k], v = b[(k + 1) % n];
        for (int i = 0; i < (int)a.size(); i++) {
            P s = a[i], t = a[(i + 1) % a.size()];
            Q ds = cross(u, v, s), dt = cross(u, v, t);
            if (ds >= Q(0))
                c.push_back(s);
            if ((ds < Q(0) && dt > Q(0)) || (ds > Q(0) && dt < Q(0))) {
                Q f = ds / (ds - dt);
                c.push_back({s.x + (t.x - s.x) * f, s.y + (t.y - s.y) * f});
            }
        }
        a = c;
    }
    Q area;
    for (int i = 0; i < (int)a.size(); i++)
        area += a[i].x * a[(i + 1) % a.size()].y - a[i].y * a[(i + 1) % a.size()].x;
    if (area < Q(0))
        area = -area;
    area /= Q(2);
    cpp_int num = area.numerator() * 100, den = area.denominator(), q = num / den;
    if (2 * (num % den) >= den)
        q++;
    cout << q / 100 << '.' << setw(2) << setfill('0') << (q % 100).convert_to<int>()
         << '\n';
}

