        if (k == n)
            continue;
        swap(a[r], a[k]);
        long long inv = power(a[r][c], p - 2, p);
        for (int j = c; j <= n; j++)
            a[r][j] = a[r][j] * inv % p;
        for (int i = r + 1; i < n; i++)
            if (a[i][c]) {
                long long f = a[i][c];
                for (int j = c; j <= n; j++)
                    a[i][j] = (a[i][j] - f * a[r][j] % p + p) % p;
            }
        cols.push_back(c);
        r++;
    }
    vector<long long> x(n);
    for (int i = r - 1; i >= 0; i--) {
        int c = cols[i];
        long long v = a[i][n];
        for (int j = c + 1; j < n; j++)
            v = (v - a[i][j] * x[j] % p + p) % p;
        x[c] = v;
    }
    long long ans = 0;
    for (auto v : x)
        ans = (ans + v) % p;
    cout << ans << '\n';
}

