                g[top[x] - 1].set(bot[x] - 1);
        for (int b = 0; b < K; b++)
            for (int x : {L[b], R[b]}) {
                int a = top[x] - 1;
                if (a >= 0 && a != b)
                    g[a].set(b);
                a = bot[x] - 1;
                if (a >= 0 && a != b)
                    g[b].set(a);
            }
        vector<int> in(K);
        for (int a = 0; a < K; a++)
            for (int b = 0; b < K; b++)
                if (g[a][b])
                    in[b]++;
        queue<int> q;
        vector<int> source;
        for (int a = 0; a < K; a++)
            if (!in[a])
                q.push(a), source.push_back(a);
        int seen = 0;
        while (!q.empty()) {
            int a = q.front();
            q.pop();
            seen++;
            for (int b = 0; b < K; b++)
                if (g[a][b]) {
                    anc[b] |= anc[a];
                    anc[b].set(a);
                    if (!--in[b])
                        q.push(b);
                }
