            for (int i = 0; i < (int)source.size(); i++)
                cout << source[i] + 1 << (i + 1 == (int)source.size() ? '\n' : ' ');
            for (int a : ask)
                cout << anc[a - 1].count() << '\n';
        }
    }
}

