it = iter(map(int, sys.stdin.buffer.read().split()))
T = next(it)
for cs in range(1, T + 1):
    K, N = next(it), next(it)
    top = [next(it) - 1 for _ in range(N)]
    bot = [next(it) - 1 for _ in range(N)]
    L = [N] * K
    R = [-1] * K
    for row in (top, bot):
        for x, a in enumerate(row):
            if a >= 0:
                L[a] = min(L[a], x)
                R[a] = max(R[a], x)
    g = [0] * K
    for x in range(N):
        if top[x] >= 0 and bot[x] >= 0 and top[x] != bot[x]:
            g[top[x]] |= 1 << bot[x]
    for b in range(K):
        for x in (L[b], R[b]):
            a = top[x]
            if a >= 0 and a != b:
                g[a] |= 1 << b
            a = bot[x]
            if a >= 0 and a != b:
                g[b] |= 1 << a
    degree = [0] * K
    for bits in g:
        while bits:
            bit = bits & -bits
            degree[bit.bit_length() - 1] += 1
            bits ^= bit
    source = [a for a in range(K) if degree[a] == 0]
    q = deque(source)
    ancestor = [0] * K
    seen = 0
    while q:
        a = q.popleft()
        seen += 1
        bits = g[a]
        value = ancestor[a] | (1 << a)
        while bits:
            bit = bits & -bits
            b = bit.bit_length() - 1
            bits ^= bit
            ancestor[b] |= value
            degree[b] -= 1
            if not degree[b]:
                q.append(b)
    ask = [next(it) - 1 for _ in range(next(it))]
    print("Case " + str(cs) + ":")
    if seen < K:
        print("no solution")
    else:
        print(*(a + 1 for a in source))
        for a in ask:
            print(ancestor[a].bit_count())

