#include <bits/stdc++.h>
using namespace std;
int main() {
    int T;
    cin >> T;
    while (T--) {
        int n;
        cin >> n;
        vector<int> d(n), g(n);
        for (int i = 0; i < n; i++)
            cin >> d[i] >> g[i];
        int M;
        cin >> M;
        vector<short> C((1 << n) * (M + 1), -1), D = C;
        function<int(int, int, bool)> solve = [&](int mask, int b, bool turn) {
            if (!mask)
                return 0;
            short &ans = (turn ? C : D)[mask * (M + 1) + b];
            if (ans >= 0)
                return (int)ans;
            if (!turn) {
                int best = 30000;
                for (int i = 0; i < n; i++)
                    if (mask >> i & 1)
                        best = min(best, solve(mask ^ (1 << i), b, true));
                ans = best;
            } else {
                int best = solve(mask, b, false);
                for (int i = 0; i < n; i++)
                    if ((mask >> i & 1) && g[i] <= b)
                        best =
                            max(best, d[i] + solve(mask ^ (1 << i), b - g[i], false));
                ans = best;
            }
            return (int)ans;
        };
        cout << solve((1 << n) - 1, M, true) << '\n';
    }
}

