int main() {
    int R, C, D;
    cin >> R >> C >> D;
    vector<string> a(R);
    int B = -1, E = -1, P = -1;
    for (int r = 0; r < R; r++) {
        cin >> a[r];
        for (int c = 0; c < C; c++) {
            if (a[r][c] == 'B')
                B = r * C + c;
            if (a[r][c] == 'E')
                E = r * C + c;
            if (a[r][c] == 'P')
                P = r * C + c;
        }
    }
    int V = R * C;
    auto bfs = [&](int s, bool wall) {
        vector<int> d(V * 2, -1);
        queue<int> q;
        d[s * 2] = 0;
        q.push(s * 2);
        while (!q.empty()) {
            int z = q.front();
            q.pop();
            int x = z / 2, r = x / C, c = x % C;
            for (auto [dr, dc] :
                 vector<pair<int, int>>{{1, 0}, {-1, 0}, {0, 1}, {0, -1}}) {
                int nr = r + dr, nc = c + dc;
                if (nr < 0 || nr >= R || nc < 0 || nc >= C)
                    continue;
                int w = z % 2 + (a[nr][nc] == 'X');
                if (w > int(wall))
                    continue;
                int y = (nr * C + nc) * 2 + w;
                if (d[y] < 0)
                    d[y] = d[z] + 1, q.push(y);
            }
        }
        return d;
    };
    auto b = bfs(B, false);
    if (P < 0) {
        cout << b[E * 2] << '\n';
        return 0;
    }
    auto e = bfs(E, false), p = bfs(P, true);
    int ans = INT_MAX;
    for (int x = 0; x < V; x++)
        if (b[x * 2] >= 0 && e[x * 2] >= 0 && a[x / C][x % C] != 'X') {
            int t = p[x * 2];
            if (p[x * 2 + 1] >= 0 && (t < 0 || p[x * 2 + 1] < t))
                t = p[x * 2 + 1];
            if (t >= 0 && t <= D)
                ans = min(ans, b[x * 2] + max(e[x * 2], t));
        }
    cout << (ans == INT_MAX ? -1 : ans) << '\n';
}

