    vector<int> a(2 * n);
    for (int i = 0; i < n; i++) {
        cin >> a[i];
        a[i + n] = a[i];
    }
    int B = max(1, (int)sqrt(2 * n));
    vector<array<int, 3>> q(Q);
    for (int z = 0; z < Q; z++) {
        int l, r;
        cin >> l >> r;
        --l;
        --r;
        if (r < l)
            r += n;
        q[z] = {l, r, z};
    }
    sort(q.begin(), q.end(), [&](auto a, auto b) {
        if (a[0] / B != b[0] / B)
            return a[0] / B < b[0] / B;
        return (a[0] / B) % 2 ? a[1] > b[1] : a[1] < b[1];
    });
    vector<int> cnt(100001), bucket(n + 1), ans(Q);
    int L = 0, R = -1, mx = 0;
    auto change = [&](int x, int delta) {
        int old = cnt[x];
        if (old)
            bucket[old]--;
        cnt[x] += delta;
        if (cnt[x])
            bucket[cnt[x]]++;
        mx = max(mx, cnt[x]);
        while (mx && !bucket[mx])
            mx--;
    };
    for (auto [l, r, id] : q) {
        while (L > l)
            change(a[--L], 1);
        while (R < r)
            change(a[++R], 1);
        while (L < l)
            change(a[L++], -1);
        while (R > r)
            change(a[R--], -1);
        ans[id] = bucket[mx] == 1 ? mx : bucket[mx];
    }
    for (int x : ans)
        cout << x << '\n';
}

