#include <bits/stdc++.h>
using namespace std;
int main() {
    int n, S, K;
    cin >> n >> S >> K;
    vector<int> bit(n + 1), loss(n + 1);
    for (int i = 1; i <= n; i++)
        bit[i] = i & -i;
    auto kth = [&](int k) {
        int x = 0;
        for (int step = 1 << __lg(n); step; step >>= 1)
            if (x + step <= n && bit[x + step] <= k) {
                k -= bit[x + step];
                x += step;
            }
        return x + 1;
    };
    int alive = n, pos = 0;
    while (alive > 1) {
        pos = (pos + S - 1) % alive;
        int x = kth(pos);
        if (++loss[x] == K) {
            for (int i = x; i <= n; i += i & -i)
                bit[i]--;
            alive--;
            pos %= alive;
        } else
            pos = (pos + 1) % alive;
    }
    cout << kth(0) << '\n';
}

