#include <bits/stdc++.h>
using namespace std;
int main() {
    int n, w;
    cin >> n >> w;
    vector<vector<int>> g[2];
    g[0].resize(n);
    g[1].resize(n);
    vector<int> in[2];
    in[0].resize(n);
    in[1].resize(n);
    for (int k = 0; k < n * (n - 1) / 2; k++) {
        int i, j, p;
        cin >> i >> j >> p;
        g[p][j - 1].push_back(i - 1);
        in[p][i - 1]++;
    }
    long long ans = 1LL * w * w;
    for (int t = 0; t < 2; t++) {
        queue<int> q;
        vector<int> d(n, 1);
        for (int i = 0; i < n; i++)
            if (!in[t][i])
                q.push(i);
        while (!q.empty()) {
            int u = q.front();
            q.pop();
            for (int v : g[t][u]) {
                d[v] = max(d[v], d[u] + 1);
                if (!--in[t][v])
                    q.push(v);
            }
        }
        ans *= *max_element(d.begin(), d.end());
    }
    cout << ans << '\n';
}

#include <bits/stdc++.h>
using namespace std;
long long solve(int mask, vector<vector<long long>> &d, vector<long long> &memo) {
    if (!mask)
        return 0;
    long long &ans = memo[mask];
    if (ans >= 0)
        return ans;
    ans = LLONG_MAX / 4;
    int i = __builtin_ctz((unsigned)mask), rest = mask ^ (1 << i);
    for (int bits = rest; bits; bits &= bits - 1) {
        int j = __builtin_ctz((unsigned)bits);
        ans = min(ans, d[i][j] + solve(rest ^ (1 << j), d, memo));
    }
    return ans;
}
int main() {
    int n, m, s, t;
    cin >> n >> m >> s;
    vector<vector<pair<int, int>>> g(n);
    vector<int> odd(n);
    long long base = 0;
    while (m--) {
        int a, b, w;
        cin >> a >> b >> w;
        --a;
        --b;
        g[a].push_back({b, w});
        g[b].push_back({a, w});
        odd[a] ^= 1;
        odd[b] ^= 1;
        base += w;
    }
    vector<int> v;
    for (int i = 0; i < n; i++)
        if (odd[i])
            v.push_back(i);
    int k = v.size();
    vector<vector<long long>> d(k, vector<long long>(k));
    for (int i = 0; i < k; i++) {
        vector<long long> dist(n, LLONG_MAX / 4);
        priority_queue<pair<long long, int>, vector<pair<long long, int>>,
                       greater<pair<long long, int>>>
            q;
        dist[v[i]] = 0;
        q.push({0, v[i]});
        while (!q.empty()) {
            auto [w, x] = q.top();
            q.pop();
            if (w != dist[x])
                continue;
            for (auto [y, c] : g[x])
                if (w + c < dist[y]) {
                    dist[y] = w + c;
                    q.push({w + c, y});
                }
        }
        for (int j = 0; j < k; j++)
            d[i][j] = dist[v[j]];
    }
    vector<long long> memo(1 << k, -1);
    cout << base + solve((1 << k) - 1, d, memo) << '\n';
}

#include <bits/stdc++.h>
using namespace std;
#include <boost/multiprecision/cpp_int.hpp>
using boost::multiprecision::cpp_int;
#include <boost/rational.hpp>
using Q = boost::rational<cpp_int>;
struct S {
    Q l, r, m, b;
};
int main() {
    int n;
    cin >> n;
    vector<S> a;
    for (int i = 0; i < n; i++) {
        int x, y, u, v;
        cin >> x >> y >> u >> v;
        if (x > u)
            swap(x, u), swap(y, v);
        Q m = Q(v - y, u - x);
        a.push_back({Q(x), Q(u), m, Q(y) - m * Q(x)});
    }
    int ans = 0;
    for (int i = 0; i < n; i++) {
        vector<pair<Q, Q>> block;
        for (int j = 0; j < n; j++)
            if (i != j) {
                Q l = max(a[i].l, a[j].l), r = min(a[i].r, a[j].r);
                if (l >= r)
                    continue;
                Q m = a[j].m - a[i].m, b = a[j].b - a[i].b;
                if (m == Q(0)) {
                    if (b >= Q(0))
                        continue;
                } else {
                    Q cross = -b / m;
                    if (m > Q(0))
                        r = min(r, cross);
                    else
                        l = max(l, cross);
                }
                if (l < r)
                    block.push_back({l, r});
            }
        sort(block.begin(), block.end());
        Q cur = a[i].l;
        for (auto [l, r] : block) {
            if (l > cur)
                ans++;
            cur = max(cur, r);
        }
        if (cur < a[i].r)
            ans++;
    }
    cout << ans << '\n';
}

