import sys
from fractions import Fraction as F

it = iter(map(int, sys.stdin.buffer.read().split()))
n = next(it)
a = []
for _ in range(n):
    x, y, u, v = (next(it) for _ in range(4))
    if x > u:
        x, y, u, v = u, v, x, y
    m = F(v - y, u - x)
    a.append((F(x), F(u), m, F(y) - m * x))
ans = 0
for i, (left, right, mi, bi) in enumerate(a):
    block = []
    for j, (lj, rj, mj, bj) in enumerate(a):
        if i == j:
            continue
        l, r = max(left, lj), min(right, rj)
        if l >= r:
            continue
        m, b = mj - mi, bj - bi
        if m == 0:
            if b >= 0:
                continue
        elif m > 0:
            r = min(r, -b / m)
        else:
            l = max(l, -b / m)
        if l < r:
            block.append((l, r))
    cur = left
    for l, r in sorted(block):
        if l > cur:
            ans += 1
        cur = max(cur, r)
    if cur < right:
        ans += 1
print(ans)
